import { useRef, useState, useEffect } from "react";
import { useNavigate, Link, useLocation } from "react-router-dom";
import Stepper from "../../../components/Stepper";
import { Field, inputClass } from "../../../components/ui";
import { canSubmitAccountForm } from "../../../utils/accountValidation";
import EmailVerificationPending from "../../../components/EmailVerificationPending";
import {
  sendSignupVerificationEmail,
  saveEmailVerificationSession,
  getEmailVerificationErrorMessage,
  isEmailVerified,
  getEmailVerificationSession,
} from "../../../services/emailVerificationApi";
import LinkioBrand from "../../../components/LinkioBrand";

const GoogleIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" aria-hidden>
    <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" />
    <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" />
    <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z" />
    <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" />
  </svg>
);

const AppleIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden>
    <path d="M17.057 10.741c-.025-2.584 2.102-3.826 2.193-3.882-1.2-1.753-3.064-1.993-3.72-2.02-1.564-.158-3.053 1.07-3.845 1.07-.792 0-2.023-1.018-3.344-.992-1.737.026-3.338 1.013-4.232 2.564-1.803 3.125-.461 7.747 1.295 10.284.858 1.24 1.879 2.637 3.218 2.587 1.29-.049 1.776-.831 3.34-.831 1.565 0 2.001.831 3.366.804 1.39-.025 2.274-1.258 3.127-2.495.986-1.442 1.392-2.839 1.416-2.912-.03-.014-2.721-1.043-2.749-4.177zm-2.046-7.394c.702-.85 1.176-2.03 1.047-3.21-.996.04-2.203.665-2.918 1.49-.64.733-1.2 1.937-1.05 3.085 1.11.086 2.219-.515 2.921-1.365z" />
  </svg>
);

function OnboardingTopBar() {
  const navigate = useNavigate();
  return (
    <div className="linkio-topbar px-8">
      <LinkioBrand />
      <button type="button" onClick={() => navigate(-1)} className="text-sm text-gray-500 hover:text-navy">
        ← Back
      </button>
    </div>
  );
}

const profBenefits = [
  "Build a verified skill profile",
  "Apply to jobs across 69 wilayas",
  "Receive freelance requests directly",
  "One profile — employee and freelancer",
];

export function ProfessionalAccountPage() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [agreedToTerms, setAgreedToTerms] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const canContinue = canSubmitAccountForm({
    email,
    password,
    confirmPassword,
    agreedToTerms,
  });

  const handleContinue = async () => {
    if (!canContinue || loading) return;
    const trimmed = email.trim();
    setLoading(true);
    setError("");
    try {
      await sendSignupVerificationEmail("professional", trimmed);
      const expiresAt = saveEmailVerificationSession("professional", trimmed);
      navigate("/professional/onboarding/verify-email", {
        state: { email: trimmed, expiresAt },
      });
    } catch (err) {
      setError(getEmailVerificationErrorMessage(err));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-cream font-sans">
      <div className="linkio-topbar px-8">
        <LinkioBrand />
        <button type="button" onClick={() => navigate(-1)} className="text-sm text-gray-500 hover:text-navy">
          ← Back
        </button>
      </div>

      <div className="flex flex-1">
        <div className="hidden lg:flex w-[42%] bg-navy-deep text-white flex-col justify-center px-14 py-16">
          <p className="text-[11px] tracking-widest text-white/50 uppercase mb-1">Professional</p>
          <p className="text-[11px] tracking-widest text-white/50 uppercase mb-8">Step 1 of 3 — Account</p>
          <h2 className="font-serif text-4xl font-normal leading-snug mb-10">
            Your next opportunity starts here.
          </h2>
          <ul className="space-y-4">
            {profBenefits.map((b) => (
              <li key={b} className="flex items-start gap-3 text-sm text-white/90">
                <span className="w-5 h-5 rounded-full bg-pro-blue/30 flex items-center justify-center text-pro-blue text-xs flex-shrink-0 mt-0.5">
                  ✓
                </span>
                {b}
              </li>
            ))}
          </ul>
        </div>

        <div className="flex-1 bg-cream flex flex-col justify-center px-8 lg:px-20 py-12">
          <h2 className="font-serif text-3xl text-navy mb-2">Create your account</h2>
          <p className="text-sm text-gray-500 mb-8">Your login credentials for Linkio.</p>

          <Field label="Email Address" className="mb-4">
            <input
              type="email"
              placeholder="you@example.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className={inputClass}
            />
          </Field>
          <Field label="Password" className="mb-4">
            <input
              type="password"
              placeholder="Enter a password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className={inputClass}
            />
            <p className="text-xs text-gray-400 mt-1.5">At least 8 characters</p>
          </Field>
          <Field label="Confirm Password" className="mb-4">
            <input
              type="password"
              placeholder="Repeat your password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className={inputClass}
            />
          </Field>

          <div className="relative flex items-center justify-center my-6">
            <div className="absolute w-full h-px bg-gray-200" />
            <span className="relative bg-cream px-4 text-xs text-gray-400">Or continue with</span>
          </div>

          <div className="flex gap-3 mb-6">
            <button type="button" className="flex-1 flex items-center justify-center gap-2 py-3 bg-white border border-gray-200 rounded-xl text-sm font-medium hover:bg-gray-50">
              <GoogleIcon /> Google
            </button>
            <button type="button" className="flex-1 flex items-center justify-center gap-2 py-3 bg-white border border-gray-200 rounded-xl text-sm font-medium hover:bg-gray-50">
              <AppleIcon /> Apple
            </button>
          </div>

          {error && (
            <p className="text-sm text-red-600 bg-red-50 border border-red-100 rounded-lg px-3 py-2 mb-4">
              {error}
            </p>
          )}

          <label className="flex items-start gap-3 text-xs text-gray-500 mb-8 cursor-pointer">
            <input
              type="checkbox"
              checked={agreedToTerms}
              onChange={(e) => setAgreedToTerms(e.target.checked)}
              className="w-4 h-4 mt-0.5 accent-navy"
            />
            <span>
              I agree to the <span className="text-navy font-semibold underline">Terms of Service</span> and{" "}
              <span className="text-navy font-semibold underline">Privacy Policy</span>
            </span>
          </label>

          <button
            type="button"
            onClick={handleContinue}
            disabled={!canContinue || loading}
            className={`w-full py-4 rounded-full text-sm font-semibold transition-all
              ${canContinue && !loading
                ? "bg-navy text-white hover:bg-navy/90"
                : "bg-navy/40 text-white/80 cursor-not-allowed"}`}
          >
            {loading ? "Sending…" : "Continue →"}
          </button>

          <p className="text-sm text-gray-500 text-center mt-6">
            Already have an account?{" "}
            <Link to="/sign-in" className="text-navy font-semibold hover:underline">
              Sign in
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
}

export function ProfessionalVerifyEmailPage() {
  return <EmailVerificationPending portal="professional" />;
}

export function ProfessionalProfileSetupPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const email = location.state?.email;
  const [skills, setSkills] = useState(["JavaScript", "React", "Node.js"]);
  const photoRef = useRef(null);

  const removeSkill = (s) => setSkills((prev) => prev.filter((x) => x !== s));

  useEffect(() => {
    if (!isEmailVerified("professional")) {
      const session = getEmailVerificationSession("professional");
      if (session?.email) {
        navigate("/professional/onboarding/verify-email", {
          replace: true,
          state: { email: session.email, expiresAt: session.expiresAt },
        });
      } else {
        navigate("/professional/onboarding/account", { replace: true });
      }
    }
  }, [navigate]);

  return (
    <div className="min-h-screen bg-cream flex flex-col font-sans">
      <OnboardingTopBar />
      <div className="flex-1 flex flex-col items-center px-6 py-8">
        <Stepper steps={["Account", "Profile", "Documents"]} current={2} variant="navy" />

        <div className="bg-white rounded-3xl border border-gray-100 p-8 md:p-10 w-full max-w-2xl shadow-sm mt-6">
          <h2 className="font-serif text-3xl text-navy mb-2">Set up your profile</h2>
          <p className="text-sm text-gray-500 mb-8">This information will be visible to businesses on the platform.</p>

          <div className="flex flex-col items-center mb-8">
            <button
              type="button"
              onClick={() => photoRef.current?.click()}
              className="w-24 h-24 rounded-full border-2 border-dashed border-gray-300 flex flex-col items-center justify-center text-gray-400 hover:border-navy hover:text-navy transition-colors"
            >
              <span className="text-2xl mb-1">👤</span>
              <span className="text-xs">Upload photo</span>
            </button>
            <input ref={photoRef} type="file" accept="image/jpeg,image/png" className="hidden" />
            <p className="text-xs text-gray-400 mt-2">JPG or PNG, max 2MB</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <Field label="First Name">
              <input placeholder="Yacine" className={inputClass} />
            </Field>
            <Field label="Last Name">
              <input placeholder="Benali" className={inputClass} />
            </Field>
            <Field label="Phone Number">
              <input placeholder="+213 6XX XXX XXX" className={inputClass} />
            </Field>
            <Field label="Wilaya">
              <input placeholder="Alger" className={inputClass} />
            </Field>
            <Field label="City">
              <input placeholder="Your city" className={inputClass} />
            </Field>
            <Field label="Years of Experience">
              <input placeholder="3" type="number" className={inputClass} />
            </Field>
            <Field label="Job Title" className="md:col-span-2">
              <input placeholder="e.g. Software Engineer" className={inputClass} />
            </Field>
          </div>

          <Field label="Skills" className="mt-4">
            <div className={`${inputClass} flex flex-wrap gap-2 items-center min-h-[48px]`}>
              {skills.map((s) => (
                <span key={s} className="inline-flex items-center gap-1 text-xs bg-pro-blue/40 text-navy px-2.5 py-1 rounded-lg">
                  {s}
                  <button type="button" onClick={() => removeSkill(s)} className="text-navy/60 hover:text-navy">
                    ×
                  </button>
                </span>
              ))}
              <span className="text-xs text-gray-400">+ Add skill</span>
            </div>
          </Field>

          <Field label="About Me" className="mt-4">
            <textarea
              rows={4}
              placeholder="Tell businesses what makes you stand out..."
              className={`${inputClass} resize-y`}
            />
          </Field>

          <div className="flex justify-between items-center mt-8">
            <button
              type="button"
              onClick={() =>
                navigate("/professional/onboarding/verify-email", { state: email ? { email } : undefined })
              }
              className="text-sm text-gray-400 hover:text-gray-900"
            >
              ← Back
            </button>
            <button
              type="button"
              onClick={() => navigate("/professional/onboarding/documents")}
              className="px-10 py-3 bg-navy text-white rounded-full text-sm font-medium hover:bg-navy/90"
            >
              Next →
            </button>
          </div>
        </div>
      </div>
      <p className="text-center text-xs text-gray-300 py-5">© 2026 Linkio. All rights reserved.</p>
    </div>
  );
}

export function ProfessionalDocumentsPage() {
  const navigate = useNavigate();
  const fileRef = useRef(null);

  return (
    <div className="min-h-screen bg-cream flex flex-col font-sans">
      <OnboardingTopBar />
      <div className="flex-1 flex flex-col items-center px-6 py-8">
        <Stepper steps={["Account", "Profile", "Documents"]} current={3} variant="navy" />

        <div className="bg-white rounded-3xl border border-gray-100 p-8 md:p-10 w-full max-w-lg shadow-sm mt-6">
          <h2 className="font-serif text-3xl text-navy mb-2">Upload your CV</h2>
          <p className="text-sm text-gray-500 mb-6">
            Your CV will be attached to your applications. Businesses will see it when you apply.
          </p>

          <input ref={fileRef} type="file" accept=".pdf,.doc,.docx" className="hidden" onChange={() => {}} />
          <button
            type="button"
            onClick={() => fileRef.current?.click()}
            className="w-full border-2 border-dashed border-gray-200 rounded-2xl py-14 flex flex-col items-center gap-2 hover:border-navy/40 transition-colors mb-4"
          >
            <span className="text-3xl text-gray-300">📄</span>
            <p className="text-sm font-medium text-gray-700">Upload your CV</p>
            <p className="text-sm text-gray-500">
              Drag & drop your file here, or <span className="text-navy font-medium">browse to upload</span>
            </p>
            <p className="text-xs text-gray-400 mt-1">PDF · DOCX · DOC accepted</p>
            <p className="text-xs text-gray-400">Maximum file size: 5 MB</p>
          </button>

          <div className="bg-amber-light border border-amber/20 rounded-xl px-4 py-3 text-sm text-amber-900 mb-8">
            Your account will need to be <strong>verified by an admin</strong> before you can apply to jobs.
            You&apos;ll receive an email once approved.
          </div>

          <div className="flex justify-between items-center">
            <button type="button" onClick={() => navigate("/professional/onboarding/profile")} className="text-sm text-gray-400 hover:text-gray-900">
              ← Back
            </button>
            <button
              type="button"
              onClick={() => navigate("/professional/onboarding/pending")}
              className="px-8 py-3 bg-navy text-white rounded-full text-sm font-medium hover:bg-navy/90"
            >
              Submit Profile →
            </button>
          </div>
        </div>
      </div>
      <p className="text-center text-xs text-gray-300 py-5">© 2026 Linkio. All rights reserved.</p>
    </div>
  );
}

export function ProfessionalPendingPage() {
  const navigate = useNavigate();

  return (
    <div className="min-h-screen bg-cream flex flex-col font-sans">
      <OnboardingTopBar />
      <div className="flex-1 flex flex-col items-center justify-center text-center px-6 py-12">
        <div className="w-16 h-16 bg-pro-blue/30 rounded-full flex items-center justify-center text-2xl mb-6">🕐</div>
        <h1 className="font-serif text-3xl text-navy mb-3">
          Profile submitted —
          <br />
          pending verification
        </h1>
        <p className="text-sm text-gray-500 max-w-md leading-relaxed mb-6">
          Our admin team will review your profile and documents within 24–48 hours. You&apos;ll receive an email once
          your account is verified.
        </p>
        <span className="inline-flex items-center gap-2 text-xs font-medium text-amber-800 bg-amber-light border border-amber/30 px-4 py-2 rounded-full mb-8">
          ⏱ Verification in progress
        </span>
        <button
          type="button"
          onClick={() => navigate("/professional/dashboard")}
          className="w-72 py-3.5 bg-navy text-white rounded-full text-sm font-medium hover:bg-navy/90 transition-all"
        >
          Go to dashboard →
        </button>
      </div>
    </div>
  );
}
